template <bool Purposed, class Result>
HydrationProbeRequest<Purposed, Result>&
HydrationProbeRequest<Purposed, Result>::enhanceChildrenIfNeeded() & {
    return *this;
}

class query_factory {
    ContextBinding binding_;

public:
    explicit query_factory(UserContext& user_context) : binding_(user_context) {}

    HydrationProbeRequest<false> hydrationProbesMinimal() const {
        return HydrationProbeRequest<false>(binding_.get(), true);
    }

    HydrationProbeRequest<false> hydrationProbes() const {
        return HydrationProbeRequest<false>(binding_.get());
    }

    HydrationProbeRequest<false> hydrationProbesWithChildren() const {
        return HydrationProbeRequest<false>(binding_.get(), true, false)
            .unlimited()
            .selectSelfFields()
            .enhanceChildrenIfNeeded();
    }
};
